#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c;scanf("%d %d",&r,&c);
vector<vector<long long>>g(r,vector<long long>(c));
for(int i=0;i<r;++i)for(int j=0;j<c;++j)scanf("%lld",&g[i][j]);
for(int j=0;j<c;++j){for(int i=0;i<r;++i){if(i)printf(" ");printf("%lld",g[i][j]);}printf("\n");}
return 0;}

